'@

$temporaryDirectory = $null
$programPath = $null
$reportPath = $null
$resultCode = 0
try {
    if ($env:OS -ne 'Windows_NT' -or -not [Environment]::Is64BitOperatingSystem) {
        throw 'Aliz Shop requires 64-bit Windows 10 or 11.'
    }
    $programBytes = [Convert]::FromBase64String($embeddedProgramBase64)
    $sha256 = [Security.Cryptography.SHA256]::Create()
    try {
        $actualSha256 = ([BitConverter]::ToString($sha256.ComputeHash($programBytes))).Replace('-', '').ToLowerInvariant()
    } finally { $sha256.Dispose() }
    if ($actualSha256 -cne $expectedSha256) {
        throw 'Embedded program checksum mismatch. No executable was launched.'
    }

    $temporaryRoot = [IO.Path]::GetFullPath([IO.Path]::GetTempPath())
    $directoryName = 'AlizShop-' + [Guid]::NewGuid().ToString('N')
    $temporaryDirectory = [IO.Path]::GetFullPath((Join-Path $temporaryRoot $directoryName))
    if ([IO.Path]::GetDirectoryName($temporaryDirectory).TrimEnd('\') -ine $temporaryRoot.TrimEnd('\')) {
        throw 'Invalid temporary directory.'
    }
    $null = [IO.Directory]::CreateDirectory($temporaryDirectory)
    $programPath = Join-Path $temporaryDirectory 'AlizShop.exe'
    $reportPath = Join-Path $temporaryDirectory 'aliz-self-test.txt'
    $stream = New-Object IO.FileStream($programPath, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::None)
    try { $stream.Write($programBytes, 0, $programBytes.Length) }
    finally { $stream.Dispose() }
    # Verify the on-disk copy as well before executing it.
    if ((Get-FileHash -LiteralPath $programPath -Algorithm SHA256).Hash.ToLowerInvariant() -cne $expectedSha256) {
        throw 'Extracted program checksum mismatch. No executable was launched.'
    }

    if ($SelfTest) {
        $process = Start-Process -FilePath $programPath -ArgumentList '--self-test' -WorkingDirectory $temporaryDirectory -WindowStyle Hidden -PassThru
    } else {
        Write-Host 'Aliz Shop By Biw Dominic - close the app to return to PowerShell.' -ForegroundColor Magenta
        $process = Start-Process -FilePath $programPath -WorkingDirectory $temporaryDirectory -PassThru
    }
    $process.WaitForExit()
    $resultCode = $process.ExitCode
    $process.Dispose()
    if ($SelfTest -and [IO.File]::Exists($reportPath)) {
        [IO.File]::ReadAllText($reportPath)
    }
    if ($resultCode -ne 0) {
        throw ('Aliz Shop exited with code {0}.' -f $resultCode)
    }
} catch {
    $resultCode = 1
    Write-Error -Message ('Aliz Shop: ' + $_.Exception.Message) -ErrorAction Continue
} finally {
    # Remove only these two known files. Never recursively delete a computed path.
    # Unexpected files, or files still in use after interruption, are left in place.
    if ($temporaryDirectory) {
        foreach ($knownPath in @($programPath, $reportPath)) {
            if ($knownPath -and [IO.File]::Exists($knownPath)) {
                $resolvedKnown = [IO.Path]::GetFullPath($knownPath)
                if ([IO.Path]::GetDirectoryName($resolvedKnown) -ieq $temporaryDirectory) {
                    try { [IO.File]::Delete($resolvedKnown) } catch { }
                }
            }
        }
        if ([IO.Directory]::Exists($temporaryDirectory)) {
            try { [IO.Directory]::Delete($temporaryDirectory, $false) } catch { }
        }
    }
}
exit $resultCode
